(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    __rhf.god(true);
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    return 'speech ' + (window.speechSynthesis ? 'present, voices ' + speechSynthesis.getVoices().length : 'missing') + '; announcer voice on ' + g.announcer.voiceOn;
  })()

(async () => {
    const g = __rhf.game;
    const w = g.env.weather;
    g.env.setTime(13);
    Object.assign(w, { cloud: 0.15, cloudTarget: 0.15, rain: 0, rainTarget: 0, timer: 1e9 });
    g.hud.biteT = 0;
    await __until(() => g.hud.cache.bite === 'slow', 60000);
    const pill = document.getElementById('bite-pill');
    const r = pill.getBoundingClientRect();
    return 'midday sun: bite reads ' + document.getElementById('hud-bite').textContent + ', pill at ' + Math.round(r.left) + ',' + Math.round(r.top) + ' ' + Math.round(r.width) + 'x' + Math.round(r.height);
  })()

(async () => {
    const g = __rhf.game;
    const w = g.env.weather;
    g.env.setTime(6);
    Object.assign(w, { cloud: 0.4, cloudTarget: 0.9, rain: 0.1, rainTarget: 0.8, timer: 1e9 });
    let said = null;
    const orig = g.announcer.say.bind(g.announcer);
    g.announcer.say = (k, o) => {
      said = k;
      return orig(k, o);
    };
    g.hud.biteT = 0;
    await __until(() => g.hud.cache.bite === 'hot', 60000);
    return 'dawn, a front and rain: bite reads ' + document.getElementById('hud-bite').textContent + ', pill class ' + document.getElementById('bite-pill').className + ', announcer said ' + said;
  })()

(() => {
    // slow frames here: keep toasts up until the picture is taken
    const T = __rhf.game.hud;
    T.toast = ((orig) =>
      function (text, kind) {
        const real = window.setTimeout;
        window.setTimeout = (f, ms) => real(f, ms + 60000);
        try {
          return orig.call(this, text, kind);
        } finally {
          window.setTimeout = real;
        }
      })(T.toast);
    return 'toasts held';
  })()

(async () => {
    await new Promise((r) => setTimeout(r, 300));
    const t = [...document.querySelectorAll('#toasts > *, .toast')].map((e) => e.textContent).join(' | ');
    return 'after a tap on the bite: ' + t;
  })()

